transforms.code:

treePath = self.params.values.treePath or 'path'
myDict = {}
treeDict = system.kanoa.utilities.convertDatasetToDict(value, str(treePath), None)
debug = False

for key, keyValue in treeDict.items():
	if debug: system.perspective.print('item is %s'%keyValue)
	nodeNames = key.split("\\")
	sortOrder = 9999
	for i, nodeName in enumerate(nodeNames):
		key = "\\".join(nodeNames[:i+1])
		if not treeDict.has_key(key):
			itemInfo = dict(keyValue)
			for k, v in itemInfo.items(): itemInfo[k] = None
			itemInfo['path'] = key
		else:
			itemInfo = treeDict[key]
			if itemInfo.has_key('sortOrder'): sortOrder = itemInfo['sortOrder']
		myDict[key] = {'nodeName': nodeName, 'sortOrder': sortOrder, 'data': itemInfo}
		if debug: system.perspective.print('i: %s, nodeName: %s, %s'%(i, nodeName, myDict[key]['data']['path']))

return myDict

import re

path = value['path'] or ''
tree = value['tree'] or {}
pathLength = len(path.split("\\")) if path != '' else 0
options = []

for k, v in tree.items():
	if path:
		sections = k.split("\\")
		if len(sections) != pathLength + 1: continue
		if k.startswith(path + "\\"):
			options.append({'value': k, 'label': v['nodeName'], 'sortOrder': v.get('sortOrder')})
	else:
		if "\\" not in k: options.append({'value': k, 'label': v['nodeName'], 'sortOrder': v.get('sortOrder')})

def naturalLabelKey(s):
	parts = re.findall(r'\d+|[^\d]+', (s or '').strip().lower())
	key = []
	for part in parts:
		if part.isdigit(): key.append((0, int(part)))
		else: key.append((1, part))
	return tuple(key)

def sortFunc(x):
	sortOrder = x.get('sortOrder')
	label = x.get('label') or ''
	return (sortOrder is None,	sortOrder if sortOrder is not None else 0, naturalLabelKey(label))

return sorted(options, key=sortFunc)
